-- Pontos da Ana: três dias completos e hoje só a entrada
SELECT 2, d.dia, TIMESTAMP(d.dia, h.hora), h.tipo, 'Escritório (dados de teste)'
  FROM (SELECT CURDATE() - INTERVAL 1 DAY AS dia UNION ALL SELECT CURDATE() - INTERVAL 2 DAY UNION ALL SELECT CURDATE() - INTERVAL 3 DAY) d
  CROSS JOIN (SELECT '08:04:00' AS hora, 1 AS tipo UNION ALL SELECT '12:01:00', 2 UNION ALL SELECT '13:02:00', 3 UNION ALL SELECT '17:20:00', 4) h;


